// Deterministic validation. No network, no LLM.
let tx;
try { tx = typeof query === 'string' ? JSON.parse(query) : query; } catch (e) { return JSON.stringify({ valid:false, errors:['Input is not valid JSON: '+e.message], validated_transaction:{} }); }
if (tx === null || typeof tx !== 'object' || Array.isArray(tx)) return JSON.stringify({valid:false,errors:['Input must be a transaction object'],validated_transaction:{}});
const errors=[]; const validCurrencies=['USD','EUR','GBP','INR','JPY']; const validTypes=['purchase','refund','transfer','withdrawal','deposit']; const validStatuses=['pending','completed','failed','cancelled']; const requiredFields=['transaction_id','customer_id','amount','currency','transaction_date','transaction_type','status'];
for (const f of requiredFields) if (tx[f]===undefined || tx[f]===null || tx[f]==='') errors.push('Missing required field: '+f);
if (tx.amount!==undefined && tx.amount!==null && tx.amount!=='') { const amt=Number(tx.amount); if(Number.isNaN(amt)) errors.push('Invalid amount: "'+tx.amount+'" is not a number'); else if(amt<=0) errors.push('Invalid amount: must be greater than zero (got '+amt+')'); }
if (tx.currency!==undefined && tx.currency!==null && tx.currency!=='' && !validCurrencies.includes(tx.currency)) errors.push('Invalid currency: "'+tx.currency+'". Allowed: '+validCurrencies.join(', '));
if (tx.transaction_type!==undefined && tx.transaction_type!==null && tx.transaction_type!=='' && !validTypes.includes(tx.transaction_type)) errors.push('Invalid transaction_type: "'+tx.transaction_type+'". Allowed: '+validTypes.join(', '));
if (tx.status!==undefined && tx.status!==null && tx.status!=='' && !validStatuses.includes(tx.status)) errors.push('Invalid transaction status: "'+tx.status+'". Allowed: '+validStatuses.join(', '));
if (tx.transaction_date!==undefined && tx.transaction_date!==null && tx.transaction_date!=='') { const dateRe=/^\d{4}-\d{2}-\d{2}$/; if(!dateRe.test(String(tx.transaction_date))) errors.push('Invalid date format: "'+tx.transaction_date+'". Expected YYYY-MM-DD'); else { const d=new Date(String(tx.transaction_date)+'T00:00:00Z'); if(Number.isNaN(d.getTime())) errors.push('Invalid date value: "'+tx.transaction_date+'"'); }}
return JSON.stringify({valid:errors.length===0,errors,validated_transaction:errors.length===0?tx:{}});
